class Solution {
  public int medianOfUniquenessArray(int[] nums) {
    int n = nums.length, max = 0;
    for (int x : nums) max = Math.max(max, x);
    boolean[] present = new boolean[max + 1];
    int distinct = 0;
    for (int x : nums) {
      if (!present[x]) {
        present[x] = true;
        distinct++;
      }
    }
    long total = (long) n * (n + 1) / 2, need = (total + 1) / 2;
    int lo = 1, hi = distinct;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (atMost(nums, max, mid) >= need) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  }

  // subarrays with at most k distinct values
  private long atMost(int[] nums, int max, int k) {
    int[] freq = new int[max + 1];
    int left = 0, distinct = 0;
    long count = 0;
    for (int right = 0; right < nums.length; right++) {
      if (freq[nums[right]]++ == 0) distinct++;
      while (distinct > k) {
        if (--freq[nums[left++]] == 0) distinct--;
      }
      count += right - left + 1;
    }
    return count;
  }
}
